static const char *find_wake_remainder(const char *text)
{
  const char *p;
  const char *q;

  if (text == NULL) {
    return NULL;
  }

  if (s_voice.wake_word[0] != '\0') {
    p = strstr(text, s_voice.wake_word);
    if (p != NULL) {
      return skip_prompt_gap(p + strlen(s_voice.wake_word));
    }
  }

  p = strstr(text, "大王");
  if (p == NULL) {
    return NULL;
  }

  q = strstr(p + strlen("大王"), "大王");
  if (q == NULL || (size_t)(q - p) > strlen("大王") + 16) {
    return NULL;
  }

  return skip_prompt_gap(q + strlen("大王"));
}

static const char *find_wake_like_remainder(const char *text)
{
  static const char *const tokens[] = {
    "大王",
    "大招",
    "大瓜",
    "大汪",
    NULL
  };

  if (text == NULL) {
    return NULL;
  }

  for (int i = 0; tokens[i] != NULL; i++) {
    const char *token = tokens[i];
    const char *p = strstr(text, token);
    const char *q;

    if (p == NULL || (size_t)(p - text) > 12) {
      continue;
    }

    q = strstr(p + strlen(token), token);
    if (q == NULL || (size_t)(q - p) > strlen(token) + 18) {
      continue;
    }

    return skip_prompt_gap(q + strlen(token));
  }

  return NULL;
}

static bool is_exit_phrase(const char *text)
{
  return text_has(text, "退出") ||
         text_has(text, "结束对话") ||
         text_has(text, "停止对话") ||
         text_has(text, "关闭对话") ||
         text_has(text, "不用了");
}

