        return;
    }

    if (strstr(host, "xiaomimimo.com") != NULL &&
        (strcmp(model, "mimo-v2.5-pro") == 0 ||
         strcmp(model, "mimo-v2-flash") == 0)) {
        snprintf(model, cap, "%s", "mimo-v2.5");
