static bool text_has(const char *text, const char *needle)
{
  return text != NULL && needle != NULL && needle[0] != '\0' &&
         strstr(text, needle) != NULL;
}

static bool ascii_equal_nocase(const char *text, const char *pattern,
                               size_t len)
{
  for (size_t i = 0; i < len; i++) {
    unsigned char a = (unsigned char)text[i];
    unsigned char b = (unsigned char)pattern[i];

    if (tolower(a) != tolower(b)) {
      return false;
    }
  }

  return true;
}

static const char *find_ascii_nocase(const char *text, const char *pattern)
{
  size_t pattern_len;

  if (text == NULL || pattern == NULL || pattern[0] == '\0') {
    return NULL;
  }

  pattern_len = strlen(pattern);
  for (const char *p = text; *p != '\0'; p++) {
    if (ascii_equal_nocase(p, pattern, pattern_len)) {
      return p;
    }
  }

  return NULL;
}

static const char *skip_prompt_gap(const char *p)
{
  while (p != NULL && *p != '\0') {
    unsigned char c = (unsigned char)*p;

    if (c == ' ' || c == '\t' || c == '\r' || c == '\n' ||
        c == ',' || c == '.' || c == '?' || c == '!' ||
        c == ':' || c == ';') {
      p++;
      continue;
    }
    if (strncmp(p, "，", strlen("，")) == 0 ||
        strncmp(p, "。", strlen("。")) == 0 ||
        strncmp(p, "？", strlen("？")) == 0 ||
        strncmp(p, "！", strlen("！")) == 0 ||
        strncmp(p, "：", strlen("：")) == 0 ||
        strncmp(p, "；", strlen("；")) == 0) {
      p += strlen("，");
      continue;
    }
    if (strncmp(p, "啊", strlen("啊")) == 0 ||
        strncmp(p, "呀", strlen("呀")) == 0 ||
        strncmp(p, "嗯", strlen("嗯")) == 0 ||
        strncmp(p, "呃", strlen("呃")) == 0 ||
        strncmp(p, "额", strlen("额")) == 0) {
      p += strlen("啊");
      continue;
    }
    break;
  }

  return p == NULL ? "" : p;
}

static const char *skip_wake_separator(const char *p)
{
  while (p != NULL && *p != '\0') {
    unsigned char c = (unsigned char)*p;

    if (c == ' ' || c == '\t' || c == '\r' || c == '\n' ||
        c == ',' || c == '.') {
      p++;
      continue;
    }
    if (strncmp(p, "，", strlen("，")) == 0 ||
        strncmp(p, "。", strlen("。")) == 0) {
      p += strlen("，");
      continue;
    }
    break;
  }

  return p == NULL ? "" : p;
}

static const char *match_openvela_after(const char *p)
{
  static const char marker[] = "openvela";

  p = skip_wake_separator(p);
  if (p == NULL || !ascii_equal_nocase(p, marker, strlen(marker))) {
    return NULL;
  }

