          break;
        }
        used += (size_t)n;
      }
    }

    return out[0] ? 0 : -ENODATA;
  }

  return -ENODATA;
}

static int parse_asr_response(const char *resp, char *text, size_t text_cap)
{
  cJSON *root;
  cJSON *choices;
  cJSON *choice;
  cJSON *message;
  cJSON *content;
  const char *direct;
  int ret;

  if (resp == NULL || text == NULL || text_cap == 0) {
    return -EINVAL;
  }

  text[0] = '\0';
  root = cJSON_Parse(resp);
  if (root == NULL) {
    return -EPROTO;
  }

  choices = cJSON_GetObjectItem(root, "choices");
  choice = cJSON_GetArrayItem(choices, 0);
  message = choice ? cJSON_GetObjectItem(choice, "message") : NULL;
  content = message ? cJSON_GetObjectItem(message, "content") : NULL;
  ret = copy_json_content(content, text, text_cap);
  if (ret == 0) {
    cJSON_Delete(root);
    return 0;
  }

  direct = json_string_at(root, "text", NULL, NULL, NULL);
  if (direct == NULL) {
    direct = json_string_at(root, "result", "text", NULL, NULL);
  }
  if (direct == NULL) {
    direct = json_string_at(root, "data", "text", NULL, NULL);
  }

  if (direct != NULL) {
    snprintf(text, text_cap, "%s", direct);
    ret = text[0] ? 0 : -ENODATA;
  }

  cJSON_Delete(root);
  return ret;
}

static int mimo_asr_recognize(const unsigned char *pcm_data,
                              size_t pcm_len,
                              char *text_out,
                              size_t text_cap)
{
  char *body;
  char *resp;
  char auth[192];
  size_t body_len = 0;
  size_t resp_len = 0;
  int status;
  int ret;

  if (pcm_data == NULL || pcm_len == 0 || text_out == NULL ||
      text_cap == 0) {
    return -EINVAL;
  }

  mimo_asr_init();
  if (s_api_key[0] == '\0') {
    syslog(LOG_ERR, "[%s] API key not configured\n", TAG);
    return -ENOENT;
  }

  body = build_asr_body(pcm_data, pcm_len, &body_len);
  if (body == NULL) {
    return -ENOMEM;
  }

  resp = calloc(1, VELACLAW_VOICE_RESP_BUF_SIZE);
  if (resp == NULL) {
    free(body);
    return -ENOMEM;
  }

  snprintf(auth, sizeof(auth), "Bearer %s", s_api_key);
  vela_header_t hdrs[] = {
    { "Content-Type", "application/json" },
    { "Accept-Encoding", "identity" },
    { "Authorization", auth },
    { NULL, NULL }
  };

  syslog(LOG_INFO, "[%s] request %zu bytes pcm via %s/%s\n",
         TAG, pcm_len, s_host, s_model);
  status = vela_https_request(s_host, s_port, "POST", s_path,
                              hdrs, body, body_len,
                              resp, VELACLAW_VOICE_RESP_BUF_SIZE,
                              &resp_len);
  free(body);

  if (status != 200) {
    syslog(LOG_ERR, "[%s] HTTP %d: %.160s\n", TAG, status, resp);
    free(resp);
    return -EIO;
  }

  ret = parse_asr_response(resp, text_out, text_cap);
  free(resp);
  if (ret != 0) {
    syslog(LOG_WARNING, "[%s] parse failed: %d\n", TAG, ret);
    return ret;
  }

  syslog(LOG_INFO, "[%s] recognized: %.80s\n", TAG, text_out);
  return 0;
}

static const voice_asr_ops_t s_mimo_asr_ops = {
  .name = "mimo",
  .init = mimo_asr_init,
  .recognize = mimo_asr_recognize,
  .deinit = NULL,
};

int mimo_asr_register(void)
{
  return voice_asr_register(&s_mimo_asr_ops);
}

